// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract WalletSignatureDecrypt {
    string public constant challengeName = "WalletSignatureDecrypt";

    address public immutable authorizedSigner;
    bytes32 public immutable challengeHash;
    bytes public encryptedFlag;

    event FlagDecrypted(address indexed player, address indexed signer, string flag);

    constructor(
        address authorizedSigner_,
        bytes32 challengeHash_,
        bytes memory encryptedFlag_
    ) {
        authorizedSigner = authorizedSigner_;
        challengeHash = challengeHash_;
        encryptedFlag = encryptedFlag_;
    }

    function messageDigest() public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", challengeHash));
    }

    function getEncryptedFlag() external view returns (bytes memory) {
        return encryptedFlag;
    }

    function decryptFlag(bytes calldata signature) external returns (string memory) {
        require(_recover(messageDigest(), signature) == authorizedSigner, "bad signer");

        bytes32 key = keccak256(signature);
        bytes memory flagBytes = new bytes(encryptedFlag.length);

        for (uint256 i = 0; i < encryptedFlag.length; i++) {
            flagBytes[i] = encryptedFlag[i] ^ key[i % 32];
        }

        string memory flag = string(flagBytes);
        emit FlagDecrypted(msg.sender, authorizedSigner, flag);
        return flag;
    }

    function _recover(bytes32 digest, bytes calldata signature) private pure returns (address) {
        require(signature.length == 65, "bad signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := calldataload(signature.offset)
            s := calldataload(add(signature.offset, 0x20))
            v := byte(0, calldataload(add(signature.offset, 0x40)))
        }

        if (v < 27) {
            v += 27;
        }

        require(v == 27 || v == 28, "bad v");
        return ecrecover(digest, v, r, s);
    }
}
